<script setup lang="ts">defineProps<{  label?: string;  disabled?: boolean;  severity?: 'primary' | 'secondary' | 'success' | 'info' | 'warning' | 'danger' | 'help';}>();defineEmits<{  click: [event: MouseEvent];}>();</script><template>  <button :class="['u-button', `u-button-${severity || 'primary'}`]" :disabled="disabled" @click="$emit('click', $event)">    <slot>{{ label }}</slot>  </button></template>